const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 18,
  })),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

// --- Build alert overlay on an HTML canvas ---
const SIZE = 512;
const canvas = document.createElement('canvas');
canvas.width = SIZE;
canvas.height = SIZE;
const ctx = canvas.getContext('2d');

// Base: semi-transparent orange-red fill
ctx.fillStyle = 'rgba(220, 40, 0, 0.55)';
ctx.fillRect(0, 0, SIZE, SIZE);

// Diagonal hazard stripes in amber
ctx.save();
ctx.globalAlpha = 0.35;
ctx.strokeStyle = 'rgba(255, 180, 0, 1.0)';
ctx.lineWidth = 28;
for (let i = -SIZE; i < SIZE * 2; i += 72) {
  ctx.beginPath();
  ctx.moveTo(i, 0);
  ctx.lineTo(i + SIZE, SIZE);
  ctx.stroke();
}
ctx.restore();

// Radial vignette to concentrate the red toward the centre
const radial = ctx.createRadialGradient(SIZE / 2, SIZE / 2, 60, SIZE / 2, SIZE / 2, SIZE * 0.75);
radial.addColorStop(0, 'rgba(255, 60, 0, 0.0)');
radial.addColorStop(1, 'rgba(180, 0, 0, 0.45)');
ctx.fillStyle = radial;
ctx.fillRect(0, 0, SIZE, SIZE);

// White border rectangle
ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
ctx.lineWidth = 14;
ctx.strokeRect(20, 20, SIZE - 40, SIZE - 40);

// Alert text
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.shadowColor = 'rgba(0,0,0,0.7)';
ctx.shadowBlur = 8;

ctx.font = 'bold 78px Arial';
ctx.fillStyle = 'rgba(255, 255, 255, 0.97)';
ctx.fillText('! ALERT !', SIZE / 2, SIZE / 2 - 48);

ctx.font = 'bold 52px Arial';
ctx.fillStyle = 'rgba(255, 230, 0, 0.97)';
ctx.fillText('FLORIDA', SIZE / 2, SIZE / 2 + 36);

ctx.font = 'bold 30px Arial';
ctx.fillStyle = 'rgba(255, 255, 255, 0.88)';
ctx.fillText('SEVERE WEATHER WARNING', SIZE / 2, SIZE / 2 + 100);

const dataUrl = canvas.toDataURL('image/png');

// --- Drape the canvas image over Florida ---
const floridaRect = Cesium.Rectangle.fromDegrees(-87.6, 24.4, -79.9, 31.1);

const alertLayer = Cesium.ImageryLayer.fromProviderAsync(
  Cesium.SingleTileImageryProvider.fromUrl(dataUrl, {
    rectangle: floridaRect,
  }),
);
alertLayer.alpha = 0.82;
viewer.imageryLayers.add(alertLayer);

// --- Frame camera over Florida peninsula (top-down) ---
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-83.5, 27.8, 1600000),
  orientation: {
    heading: 0.0,
    pitch: Cesium.Math.toRadians(-88),
    roll: 0.0,
  },
});
